    ('a2720609-acca-47c5-b778-15568e68a67e'::uuid, 'antiquity', '10', '5', 'card-stats-2026-10-04b-rollback:a2720609-acca-47c5-b778-15568e68a67e:antiquity', 'rollback of card-stats-2026-10-04b: antiquity ''5'' restored on Cave of Aurignac', 'f7c39ddd0959dcd61b45c1b0c72fcc89', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "antiquity = 10 from period_start -50000"}, {"source": "production export a991f0242bf4f80c (2026-10-04 18:08:44.180088+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 133 journalled input value(s) put back reproduce the stored card_stats in all 59724 cells (basis: wave 2026-10-04''s own export (2026-10-04 13:55:46.282309+00))"}, {"source": "remediation_change_log:28732", "url": "remediation_change_log", "quote": "phase3:batch-0185:chunk-0001: period_start ''-500'' -> ''-45000''"}, {"source": "remediation_change_log:30469", "url": "remediation_change_log", "quote": "2026-09-22_mechanical-period-name: period_name ''500 BC - 1 AD'' -> ''< 4500 BC''"}, {"source": "remediation_change_log:35922", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: period_name ''< 4500 BC'' -> ''500 BC - 1 AD''"}, {"source": "remediation_change_log:35923", "url": "remediation_change_log", "quote": "2026-09-25_mechanical-journal-reversal-3: period_start ''-45000'' -> ''-500''"}, {"source": "remediation_change_log:43635", "url": "remediation_change_log", "quote": "phase4:p4-0078:chunk-0001: description ''The Cave of Aurignac is an archaeological site in the commune of Aurignac, Haute-Garonne, southwestern France. Excavated since 1860, it is the type site of the Aurignacian culture, the earliest known culture attributed to modern humans in western Eurasia [1]. Tool assemblages date from approximately 45,000 to 26,000 years BP, representing the Upper Paleolithic period [1]. In recognition of its scientific significance and the pioneering 19th-century work of Edouard Lartet, the cave was officially declared a French Historic Monument on May 26, 1921 [1].'' -> ''The Cave of Aurignac is an archaeological site in the commune of Aurignac, Haute-Garonne department in southwestern France [1]. The eponymous location represents the type site of the Aurignacian, the earliest known culture attributed to modern humans in western Eurasia [1]. In recognition of its significance for various scientific fields and the 19th-century pioneering work of Édouard Lartet the Cave of Aurignac was officially declared a national Historic Monument of France by order of May 26, 1921 [1]. The Aurignac limestone grotto is located in the Aurignac commune, approximately 1.5 km northwest of the town centre, on the southern side of the Rodes rivulet valley [1]. Pioneer paleontologist Édouard Lartet led the first excavation from 1860 to 1863 and recovered advanced tools, such as finely cut flints, struck from prepared core and variously worked bones and reindeer antlers, a great number of fossilized human bone and ceramic fragments, although the latter had confirmedly been buried during the Chalcolithic (around 6,000 to 4,000 years BP) [1].''"}, {"source": "remediation_change_log:121643", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s007: period_name ''500 BC - 1 AD'' -> None"}, {"source": "remediation_change_log:121644", "url": "remediation_change_log", "quote": "2026-09-26b_fields-wd1-s007: period_start ''-500'' -> None"}, {"source": "remediation_change_log:157633", "url": "remediation_change_log", "quote": "served-image-2026-09-30-022: thumbnail_url ''/data/images/wiki/a2720609/hero.webp'' -> ''/data/images/wiki/a2720609/Aurignac 2 1.webp''"}, {"source": "remediation_change_log:302171", "url": "remediation_change_log", "quote": "2026-10-04a_fields-wd4-s001: period_name None -> ''< 4500 BC''"}, {"source": "remediation_change_log:302172", "url": "remediation_change_log", "quote": "2026-10-04a_fields-wd4-s0